<template><SuperAdminLayout><main class="page"><header><h1>7.3 Restore System</h1></header><p v-if="notice" :class="{error}">{{notice}}</p><section><h2>Restore Access</h2><form @submit.prevent="restore"><label>Active Shutdown<select v-model="f.id" required><option value="" disabled>Select a shutdown record</option><option v-for="x in active" :key="x.id" :value="x.id">#{{x.id}} — {{title(x.scope)}} ({{x.reason}})</option></select></label><label>Restore Scope<select v-model="f.scope"><option value="entire_platform">Entire Platform</option><option value="all_customers">All Customer Accounts</option><option value="one_customer">One Customer Account</option></select></label><label>Customer Account No.<input :value="current?.customer_id?`CUST-${String(current.customer_id).padStart(6,'0')}`:'Entire Platform'" readonly></label><label>Restore Date<input v-model="f.date" type="date"></label><label>Restore Time<input v-model="f.time" type="time"></label><fieldset><legend>Security Check Completed</legend><label><input v-model="f.checked" type="radio" :value="true"> Yes</label><label><input v-model="f.checked" type="radio" :value="false"> No</label></fieldset><label>Restored By<input :value="userName" readonly></label><label>Approved By<input value="System Admin" readonly></label><label>Administrator Password<input v-model="f.password" type="password" required></label><div class="actions"><button class="success" :disabled="!f.checked">✓ RESTORE ACCESS</button><button type="button" @click="reset">Reset</button></div></form></section></main></SuperAdminLayout></template>
<script setup>import{computed,onMounted,reactive,ref,watch}from'vue';import SuperAdminLayout from'../components/SuperAdminLayout.vue';import client from'../api/client';import{authState}from'../store/auth';const d=new Date(),today=d.toISOString().slice(0,10),time=d.toTimeString().slice(0,5),active=ref([]),notice=ref(''),error=ref(false),f=reactive({id:'',scope:'entire_platform',date:today,time,checked:true,password:''}),userName=computed(()=>authState.user?.name||'System Admin'),current=computed(()=>active.value.find(x=>String(x.id)===String(f.id))),title=v=>String(v||'').replaceAll('_',' ').replace(/\b\w/g,x=>x.toUpperCase());async function load(){const r=await client.get('/super-admin/emergency-shutdowns',{params:{status:'active',per_page:100}});active.value=r.data.data?.data||[]}watch(current,x=>{if(x)f.scope=x.scope});function reset(){Object.assign(f,{id:'',scope:'entire_platform',date:today,time,checked:true,password:''})}async function restore(){if(!f.id){error.value=true;notice.value='Select an active shutdown record.';return}try{await client.post(`/super-admin/emergency-shutdowns/${f.id}/restore`,{password:f.password});error.value=false;notice.value='System access has been restored.';reset();load()}catch(e){error.value=true;notice.value=e.response?.data?.message||'Unable to restore access.'}}onMounted(load)</script>
<style scoped>.page{color:#071541}.page h1{margin:0 0 18px;font-size:2rem}.page>p{padding:11px 14px;border:1px solid #a4d4b0;border-radius:6px;background:#effaf1;color:#17632d}.page>p.error{border-color:#ffc1c1;background:#fff2f2;color:#b20d0d}section{padding:16px;border:1px solid #dbe4ef;border-radius:7px;background:#fff}h2{margin:0 0 14px;padding-bottom:11px;border-bottom:1px solid #dbe4ef;color:#ed1010;font-size:1rem}form{display:grid;grid-template-columns:repeat(3,minmax(160px,1fr));gap:14px 22px}label,fieldset{display:grid;gap:6px;min-width:0;border:0;padding:0;font-size:.7rem;font-weight:800}legend{margin-bottom:6px;font-size:.7rem;font-weight:800}fieldset label{display:inline-flex;gap:6px;margin-right:12px;font-weight:500}input,select,button{box-sizing:border-box;width:100%;height:36px;border:1px solid #cad8ed;border-radius:5px;background:#fff;padding:0 10px;font:500 .77rem inherit}fieldset input{width:auto;height:auto}.actions{grid-column:2/-1;display:grid;grid-template-columns:1fr 1fr;gap:12px}.success{background:#078234;border-color:#078234;color:#fff;font-weight:700}button:disabled{opacity:.5}@media(max-width:650px){form{grid-template-columns:1fr}.actions{grid-column:auto}.page h1{font-size:1.55rem}}</style>
